import { Search } from "lucide-react";
import { Input } from "@/components/ui/input";
import { ChannelBadge } from "../shared/ChannelBadge";
import { cn } from "@/lib/utils";
import type { ChatbotChannel, Contact, Conversation, ConversationStatus, PageRequest } from "@/types/chatbot";
import { chatbotChannelFilterSchema, conversationStatusFilterSchema, pageSortSchema } from "@/services/chatbot/schemas";
import { CHATBOT_CHANNELS } from "@/services/chatbot/constants";

interface ConversationListProps { conversations: Conversation[]; contacts: Contact[]; selectedId: string | null; search: string; status: ConversationStatus | "all"; channel: ChatbotChannel | "all"; sort: NonNullable<PageRequest["sort"]>; onSearch: (value: string) => void; onStatus: (value: ConversationStatus | "all") => void; onChannel: (value: ChatbotChannel | "all") => void; onSort: (value: NonNullable<PageRequest["sort"]>) => void; onSelect: (id: string) => void }
const time = (value: string) => new Intl.DateTimeFormat("pt-BR", { hour: "2-digit", minute: "2-digit" }).format(new Date(value));
export function ConversationList({ conversations, contacts, selectedId, search, status, channel, sort, onSearch, onStatus, onChannel, onSort, onSelect }: ConversationListProps) {
  return <section className="flex min-h-0 flex-col border-r border-white/5" aria-label="Conversas">
    <div className="space-y-2 border-b border-white/5 p-3"><div className="relative"><Search className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-slate-500" /><Input value={search} onChange={(event) => onSearch(event.target.value)} placeholder="Buscar conversa" aria-label="Buscar conversas" className="h-10 border-white/10 bg-white/[0.03] pl-9 text-sm md:h-9" /></div>
      <div className="grid grid-cols-3 gap-1.5"><select value={status} onChange={(event) => { const parsed = conversationStatusFilterSchema.safeParse(event.target.value); if (parsed.success) onStatus(parsed.data); }} aria-label="Filtrar por status" className="h-10 rounded-md border border-white/10 bg-slate-950 px-2 text-xs text-slate-300 outline-none focus:ring-2 focus:ring-indigo-500 md:h-8"><option value="all">Status</option><option value="open">Abertas</option><option value="pending">Pendentes</option><option value="resolved">Encerradas</option></select><select value={channel} onChange={(event) => { const parsed = chatbotChannelFilterSchema.safeParse(event.target.value); if (parsed.success) onChannel(parsed.data); }} aria-label="Filtrar por canal" className="h-10 rounded-md border border-white/10 bg-slate-950 px-2 text-xs text-slate-300 outline-none focus:ring-2 focus:ring-indigo-500 md:h-8"><option value="all">Canal</option>{CHATBOT_CHANNELS.map((item) => <option key={item} value={item}>{item}</option>)}</select><select value={sort} onChange={(event) => { const parsed = pageSortSchema.safeParse(event.target.value); if (parsed.success) onSort(parsed.data); }} aria-label="Ordenar conversas" className="h-10 rounded-md border border-white/10 bg-slate-950 px-2 text-xs text-slate-300 outline-none focus:ring-2 focus:ring-indigo-500 md:h-8"><option value="recent">Recentes</option><option value="oldest">Antigas</option><option value="name">Nome</option></select></div></div>
    <div className="min-h-0 flex-1 overflow-y-auto">{conversations.map((conversation) => { const contact = contacts.find((item) => item.id === conversation.contactId); if (!contact) return null; return <button key={conversation.id} type="button" onClick={() => onSelect(conversation.id)} aria-pressed={selectedId === conversation.id} className={cn("flex w-full gap-3 border-b border-white/5 p-3 text-left transition-colors hover:bg-white/[0.04] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-indigo-500", selectedId === conversation.id && "bg-indigo-500/10")}>
      <span className="grid size-9 shrink-0 place-items-center rounded-full bg-slate-800 text-xs font-semibold text-slate-200">{contact.initials}</span><span className="min-w-0 flex-1"><span className="flex items-center gap-2"><span className="truncate text-sm font-medium text-slate-200">{contact.name}</span><time className="ml-auto text-[10px] text-slate-500">{time(conversation.updatedAt)}</time></span><span className="mt-1 flex items-center gap-1.5"><ChannelBadge channel={conversation.channel} compact /><span className="truncate text-xs text-slate-500">{conversation.lastMessage}</span>{conversation.unread > 0 && <span className="ml-auto grid size-5 shrink-0 place-items-center rounded-full bg-indigo-500 text-[10px] font-semibold text-white" aria-label={`${conversation.unread} mensagens não lidas`}>{conversation.unread}</span>}</span></span>
    </button>; })}</div>
  </section>;
}
